def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    r = int(n ** 0.5)
    # Correct any floating-point round-off near the boundary.
    if (r + 1) * (r + 1) == n:
        r += 1
    elif r * r > n:
        r -= 1
    return r
